namespace sv_17d7acbf63814ac28256e046a25eef75.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();
    private static readonly string[] SampleMessages =
    [
        "Deployment completed successfully",
        "New user registered",
        "Disk usage above 80%",
        "Backup finished",
        "Certificate expiring in 7 days",
        "Build pipeline failed",
        "Security scan completed — no issues found",
        "Database migration applied",
        "Service restarted automatically",
        "New comment on pull request #42"
    ];

    public NotificationService()
    {
        // Seed initial notifications
        var now = DateTime.UtcNow;
        for (var i = 0; i < 3; i++)
        {
            _notifications.Add(new Notification
            {
                Id = _nextId++,
                Message = SampleMessages[i],
                Timestamp = now.AddMinutes(-(3 - i))
            });
        }
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>
    /// Returns notifications added after the given ID, and randomly generates
    /// new ones to simulate a live system.
    /// </summary>
    public Task<List<Notification>> GetNewNotificationsAfterAsync(int lastSeenId)
    {
        lock (_lock)
        {
            // ~40% chance of a new notification each poll
            if (Random.Shared.NextDouble() < 0.4)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = SampleMessages[Random.Shared.Next(SampleMessages.Length)],
                    Timestamp = DateTime.UtcNow
                });
            }

            var newer = _notifications
                .Where(n => n.Id > lastSeenId)
                .OrderByDescending(n => n.Timestamp)
                .ToList();

            return Task.FromResult(newer);
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using sv_17d7acbf63814ac28256e046a25eef75.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we don't re-fetch data that was already persisted from prerender
        notifications ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender,
            // so this only fires once the page is live and interactive
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var lastId = notifications?.Max(n => n.Id) ?? 0;
            var newer = await NotificationService.GetNewNotificationsAfterAsync(lastId);

            if (newer.Count > 0 && notifications is not null)
            {
                notifications.InsertRange(0, newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

